   116  static gchar *
   117  fu_coswid_firmware_strndup(cbor_item_t *item)
   118  {
   119          if (!cbor_string_is_definite(item))
   120                  return NULL;
   121          return g_strndup((const gchar *)cbor_string_handle(item), cbor_string_length(item));
   122  }
