   124  typedef gboolean (*FuCoswidFirmwareItemFunc)(FuCoswidFirmware *self,
   125                                               cbor_item_t *item,
   126                                               gpointer user_data,
   127                                               GError **error) G_GNUC_WARN_UNUSED_RESULT;
   128
   129  static gboolean
   130  fu_coswid_firmware_parse_one_or_many(FuCoswidFirmware *self,
   131                                       cbor_item_t *item,
   132                                       FuCoswidFirmwareItemFunc func,
   133                                       gpointer user_data,
   134                                       GError **error)
   135  {
   136          /* one */
   137          if (cbor_isa_map(item))
   138                  return func(self, item, user_data, error);
   139
   140          /* many */
   141          if (cbor_isa_array(item)) {
   142                  for (guint j = 0; j < cbor_array_size(item); j++) {
   143                          g_autoptr(cbor_item_t) value = cbor_array_get(item, j);
   144                          if (!func(self, value, user_data, error))
   145                                  return FALSE;
   146                  }
   147                  return TRUE;
   148          }
   149
   150          /* not sure what to do */
   151          g_set_error_literal(error,
   152                              FWUPD_ERROR,
   153                              FWUPD_ERROR_INVALID_DATA,
   154                              "neither an array or map");
   155          return FALSE;
   156  }
