   158  static gboolean
   159  fu_coswid_firmware_parse_meta(FuCoswidFirmware *self,
   160                                cbor_item_t *item,
   161                                gpointer user_data,
   162                                GError **error)
   163  {
   164          FuCoswidFirmwarePrivate *priv = GET_PRIVATE(self);
   165          struct cbor_pair *pairs = cbor_map_handle(item);
   166
   167          for (gsize i = 0; i < cbor_map_size(item); i++) {
   168                  FuCoswidTag tag_id = cbor_get_uint8(pairs[i].key);
   169                  if (tag_id == FU_COSWID_TAG_SUMMARY) {
   170                          priv->summary = fu_coswid_firmware_strndup(pairs[i].value);
   171                  } else if (tag_id == FU_COSWID_TAG_COLLOQUIAL_VERSION) {
   172                          priv->colloquial_version = fu_coswid_firmware_strndup(pairs[i].value);
   173                  } else {
   174                          g_debug("unhandled tag %s from %s",
   175                                  fu_coswid_tag_to_string(tag_id),
   176                                  fu_coswid_tag_to_string(FU_COSWID_TAG_SOFTWARE_META));
   177                  }
   178          }
   179
   180          /* success */
   181          return TRUE;
   182  }
