   184  static gboolean
   185  fu_coswid_firmware_parse_link(FuCoswidFirmware *self,
   186                                cbor_item_t *item,
   187                                gpointer user_data,
   188                                GError **error)
   189  {
   190          FuCoswidFirmwarePrivate *priv = GET_PRIVATE(self);
   191          struct cbor_pair *pairs = cbor_map_handle(item);
   192          g_autoptr(FuCoswidFirmwareLink) link = g_new0(FuCoswidFirmwareLink, 1);
   193
   194          for (gsize i = 0; i < cbor_map_size(item); i++) {
   195                  FuCoswidTag tag_id = cbor_get_uint8(pairs[i].key);
   196                  if (tag_id == FU_COSWID_TAG_HREF) {
   197                          link->href = fu_coswid_firmware_strndup(pairs[i].value);
   198                  } else if (tag_id == FU_COSWID_TAG_REL) {
   199                          if (cbor_isa_negint(pairs[i].value))
   200                                  link->rel = (-1) - cbor_get_uint8(pairs[i].value);
   201                          else
   202                                  link->rel = cbor_get_uint8(pairs[i].value);
   203                  } else {
   204                          g_debug("unhandled tag %s from %s",
   205                                  fu_coswid_tag_to_string(tag_id),
   206                                  fu_coswid_tag_to_string(FU_COSWID_TAG_LINK));
   207                  }
   208          }
   209
   210          /* success */
   211          g_ptr_array_add(priv->links, g_steal_pointer(&link));
   212          return TRUE;
   213  }
