   245  static gboolean
   246  fu_coswid_firmware_parse_hash_array(FuCoswidFirmware *self,
   247                                      cbor_item_t *item,
   248                                      gpointer user_data,
   249                                      GError **error)
   250  {
   251          for (guint j = 0; j < cbor_array_size(item); j++) {
   252                  g_autoptr(cbor_item_t) value = cbor_array_get(item, j);
   253                  if (!fu_coswid_firmware_parse_hash(self, value, user_data, error))
   254                          return FALSE;
   255          }
   256          return TRUE;
   257  }
