   259  static gboolean
   260  fu_coswid_firmware_parse_file(FuCoswidFirmware *self,
   261                                cbor_item_t *item,
   262                                gpointer user_data,
   263                                GError **error)
   264  {
   265          FuCoswidFirmwarePrivate *priv = GET_PRIVATE(self);
   266          struct cbor_pair *pairs = cbor_map_handle(item);
   267          g_autoptr(FuCoswidFirmwarePayload) payload = fu_coswid_firmware_payload_new();
   268
   269          for (gsize i = 0; i < cbor_map_size(item); i++) {
   270                  FuCoswidTag tag_id = cbor_get_uint8(pairs[i].key);
   271                  if (tag_id == FU_COSWID_TAG_FS_NAME) {
   272                          payload->name = fu_coswid_firmware_strndup(pairs[i].value);
   273                  } else if (tag_id == FU_COSWID_TAG_SIZE) {
   274                          payload->size = cbor_get_int(pairs[i].value);
   275                  } else if (tag_id == FU_COSWID_TAG_HASH) {
   276                          if (cbor_isa_array(pairs[i].value) &&
   277                              cbor_array_size(pairs[i].value) >= 1) {
   278                                  g_autoptr(cbor_item_t) value = cbor_array_get(pairs[i].value, 0);
   279                                  /* we can't use fu_coswid_firmware_parse_one_or_many() here as
   280                                   * the hash is an array, not a map -- for some reason */
   281                                  if (cbor_isa_array(value)) {
   282                                          if (!fu_coswid_firmware_parse_hash_array(self,
   283                                                                                   pairs[i].value,
   284                                                                                   payload,
   285                                                                                   error))
   286                                                  return FALSE;
   287                                  } else {
   288                                          if (!fu_coswid_firmware_parse_hash(self,
   289                                                                             pairs[i].value,
   290                                                                             payload,
   291                                                                             error))
   292                                                  return FALSE;
   293                                  }
   294                          } else {
   295                                  g_set_error(error,
   296                                              FWUPD_ERROR,
   297                                              FWUPD_ERROR_INVALID_DATA,
   298                                              "hashes neither an array or array of array");
   299                                  return FALSE;
   300                          }
   301                  } else {
   302                          g_debug("unhandled tag %s from %s",
   303                                  fu_coswid_tag_to_string(tag_id),
   304                                  fu_coswid_tag_to_string(FU_COSWID_TAG_FILE));
   305                  }
   306          }
   307
   308          /* success */
   309          g_ptr_array_add(priv->payloads, g_steal_pointer(&payload));
   310          return TRUE;
   311  }
